// Generated by scripts/generate-workflow-blueprints.ts (extra questions); edit the specs there and re-run rather than editing by hand.
import { o, s, type QuestionSet } from "@/lib/interview-questions";

const bank: QuestionSet = {
  subjective: [
    s(5, "Redis holds live reservations but Postgres is the system of record. How do you keep them consistent, and what happens if Redis loses data?", "Every reserve, commit and release writes a movement row to Postgres, ideally through an outbox or a stream that is replayed in order with movement IDs, so replays are idempotent. Redis is a fast projection: available equals on-hand minus active reservations. A reconciliation job compares the Redis counters with the Postgres ledger per store and SKU, and it alerts on drift and repairs it. If Redis fails over and loses recent writes, I rebuild the affected store's keys from Postgres. That means on-hand stock plus unexpired reservations. While I rebuild, I briefly mark that store's catalog read-only or not serviceable. Selling during a rebuild risks overselling, and the hard rule is never to oversell, so pausing one store for a short time is the right trade."),
    s(5, "How would you design the idempotency key for order creation, and where is it enforced?", "The client generates a UUID when the user taps 'place order' and reuses it on every retry of that attempt. The order service stores the key with a hash of the request, so the customer, store, lines and amount, under a unique constraint in Postgres. On a retry with the same key and the same hash, it returns the original response. If the same key arrives with a different payload, that is a client bug, so it returns a conflict. The key is scoped to the user and expires after a window, for example a day. I pass the same key downstream as the reservation ID and as the payment gateway's idempotency or merchant reference. That way a retried request cannot double-reserve stock or double-charge the customer, even when the first attempt timed out and its real outcome is unknown."),
    s(5, "Payment succeeds, but the success callback arrives after the reservation TTL has expired and the stock was released. What do you do?", "First, I would try to re-reserve the same lines atomically. If stock is still there, the order confirms normally. If some lines are gone, I must not fulfil items the store doesn't have. I either confirm the available lines and refund the missing ones exactly through the ledger, or, if a key item is missing, I cancel and refund in full, and I tell the customer clearly. To make this rare, I set the TTL above the realistic payment window. I extend the reservation when the gateway reports the payment is pending, and I reconcile with the gateway by polling as well as through webhooks. I also track late-success counts as a metric, because a rising count means the TTL or the payment flow needs tuning."),
    s(5, "Why does dispatch match a rider while picking is still underway, and what are the risks?", "Picking and packing take a fixed part of a short budget. If the rider search only starts after packing, the bag waits on the shelf while the search and the rider's travel back to the store add their time on top. Starting the match early overlaps the two, so a rider arrives as the bag is sealed. The risks are idle riders when picking is slow or short-picked, and over-commitment when two stores compete for the same rider. I handle this by using a predicted pack-complete time from pick progress, so the match triggers when the predicted pack time is close to the rider's ETA. I also allow reassignment until the rider has accepted and is close, and I measure both rider wait time and bag wait time to tune the trigger."),
    s(4, "How would you decide whether two orders can be batched onto one rider?", "Both orders must come from the same store and be packed at roughly the same time. For each candidate pair, I compute the route that serves both drop points in either order. I accept the batch only if each order's predicted delivery time still meets its own promise with a safety margin. I also check rider constraints: bag capacity, weight and cold-chain items. The decision runs on a short time window, so I don't hold the first order waiting for a second. If no partner appears within a few seconds of the pack-complete prediction, the order goes solo. Batching saves rider cost, but in a 10-minute model it is opportunistic. The promise always wins over utilisation."),
    s(4, "Estimate the load on the tracking service and describe how you would scale it.", "I would state the assumptions explicitly. Say a city has R active riders at peak, each sending a GPS ping every few seconds. Inbound load is about R divided by the interval in writes per second, and each ping is small, around a hundred bytes. Outbound load depends on how many customers are watching: one WebSocket per active order, plus ops dashboards. I partition pings by rider_id onto Kafka or a similar log. Stateless tracking workers keep the last few points per rider in memory or Redis to smooth the location and compute the ETA. WebSocket gateways scale horizontally behind sticky routing, keyed by order_id, and a pub/sub layer fans out updates. I store raw pings cheaply for a short retention period and keep only summaries long-term."),
    s(4, "How do you smooth noisy GPS and keep the ETA shown to the customer stable?", "Raw GPS jumps, especially between tall buildings. I drop pings with poor reported accuracy or impossible speeds, then apply a simple filter such as a Kalman filter or exponential smoothing. I also snap the point to the road network when map data allows it. The ETA comes from the remaining route distance and recent segment speeds, adjusted for the rider's observed pace. To avoid flicker, I only push an update when the ETA changes by more than a threshold, and I allow it to rise only gradually unless there's a real event such as the rider stopping. The map marker is interpolated on the client between pings so movement looks continuous, and the server stays the source of truth."),
    s(5, "Walk me through the short-pick flow when a picker scans an empty bin.", "The picker scans the bin, and the app marks the line short. The pick service emits an item.short event, and inventory writes a correction movement, so stock is adjusted down and the SKU's availability updates for other shoppers. The order line moves to a pending-substitution state. The system suggests a substitute that is in stock in this store, similar in brand, size and price, and pushes it to the customer with a short approval window. The picker continues with other lines so picking doesn't stall. If the customer approves, the substitute is reserved and picked. If they reject it or time out, the line is dropped. The final bill is computed from what was actually packed, and the difference is refunded exactly through the ledger. The packing step verifies the bag against the final line list."),
    s(4, "How would you design the payment and refund ledger so the customer is never charged for undelivered items?", "I would use a double-entry ledger in Postgres. Every money movement is an immutable entry pair, for example customer payable against order revenue. Refunds are new reversing entries, never edits. Each entry references order_id, line_id and an idempotency key, so a retried refund cannot post twice. The billable amount is derived from packed and delivered lines, not from the cart. Where the payment method supports it, I authorise at checkout and capture only the final amount after packing, so drops never reach the customer's statement. Otherwise, I capture and refund the difference automatically. A daily reconciliation matches ledger totals against gateway settlement reports, and every mismatch becomes a tracked exception."),
    s(4, "How does serviceability protect a store that is overloaded at peak?", "Each store publishes its live capacity signals: orders in the pick queue, active pickers, riders at or near the store, and predicted pack and dispatch times. Serviceability combines these into a load state. As load rises, it first lengthens the promise for that store, then shrinks the coverage to nearer H3 cells, and finally marks the store not serviceable. This is better than accepting orders and missing the promise. The state is cached with a short TTL and has hysteresis, so a store doesn't flap between open and closed. Checkout re-checks the state, so a user who browsed a minute ago can't place an order into a store that has since hit its limit."),
    s(4, "How do you keep the per-store catalog availability fresh without hammering inventory?", "The catalog listing is served from a cache keyed by store_id. It holds static data such as names, images and prices, and a separate availability bitmap or set of sellable SKUs. Inventory publishes availability-change events only when a SKU crosses zero or a low-stock threshold, not on every unit, and catalog consumers update the set. A short client TTL handles anything missed. The cache can be slightly stale, and that's acceptable because the Redis reservation at checkout is the real gate. If an item shown as available fails to reserve, the user sees a clear 'just sold out' message and the cart adjusts. I'd track that failure rate as a measure of catalog freshness."),
    s(4, "How do you make sure order.confirmed reaches Kafka exactly when the order is confirmed in the database?", "I'd use a transactional outbox. In the same Postgres transaction that marks the order confirmed and commits the reservation movements, I insert an outbox row with the event payload. A relay process, either a polling publisher or change data capture with something like Debezium, publishes outbox rows to Kafka and marks them sent. This avoids the dual-write problem where the database commits but publishing fails, or the reverse. Delivery is at least once, so every consumer, including the pick service, deduplicates on event_id or order_id and treats repeats as no-ops. I partition by store_id or order_id so that events for one order stay in order."),
    s(4, "What partition key would you use for order events in Kafka, and why?", "For the pick and dispatch pipeline, I'd partition by store_id. Each store's pick service then reads a consistent, ordered stream of its own orders, and one consumer can own one store's queue. The risk is skew: a very busy store creates a hot partition. With enough partitions and a hash spread, that's usually manageable. If not, I'd key by order_id, which still keeps the lifecycle of each order in order, and have the store service filter what it needs. Order lifecycle events such as confirmed, short, packed and delivered must keep per-order ordering, so they always share the same key. Consumers are idempotent because rebalances can replay messages."),
    s(4, "Sketch the core data model for orders and inventory.", "For orders: orders(order_id, user_id, store_id, status, promise_at, idempotency_key, created_at), order_lines(line_id, order_id, sku_id, qty, unit_price, status such as reserved, picked, short, substituted or dropped) and order_events for the audit trail. For inventory: stock(store_id, sku_id, on_hand, version) and inventory_movements(movement_id, store_id, sku_id, delta, type such as receive, reserve, commit, release, short or adjust, ref_id, created_at), which is append-only. For reservations: reservation_id, order_id, lines and expires_at. Redis mirrors available stock per store and SKU. Fulfilment adds pick_tasks, bags(bag_id, order_id, label) and dispatch assignments. Money lives in ledger_entries. I'd partition the large tables by store or time."),
    s(3, "The dark store loses internet for several minutes during peak. How should the system behave?", "The store apps should work offline-first. Pickers already have their pick lists cached locally, they keep scanning, and the scans queue on the device with timestamps and idempotent event IDs. When the link returns, the events sync and are deduplicated. Centrally, the heartbeat from the store stops, so serviceability marks the store not serviceable for new orders. Confirmed orders keep their status, and customers get an honest delay message. Rider handover can use a locally verifiable bag barcode with sync later. The main risk is inventory drift during the outage, so after reconnection I'd reconcile movements before reopening the store. A backup cellular link per store is worth its cost."),
    s(3, "How do you secure delivery confirmation with an OTP, and what fraud does it prevent?", "The OTP is generated server-side per order, stored hashed, and shown only in the customer's app. The rider enters what the customer tells them. The server validates it with limited attempts and a short expiry, and it also checks that the rider's last GPS point is near the drop location. This stops riders from marking orders delivered without handing them over, and it gives evidence when a customer disputes a delivery. I'd provide a fallback for customers who can't access the app, such as a support call-back flow, and log every override. Rate limiting and alerts on riders with unusual override or failure patterns catch collusion that the OTP alone misses."),
    s(4, "What privacy concerns exist around customer addresses and live rider locations, and how do you handle them?", "Customer addresses and phone numbers are personal data under India's DPDP Act, so I'd collect only what delivery needs and encrypt it at rest. Riders see an address only for active orders, and calls go through masked numbers via a telephony proxy. Customer location for serviceability can be reduced to the H3 cell rather than kept as exact coordinates. A rider's live location is shared with a customer only during that order's last-mile leg, and the stream stops at delivery. Raw GPS traces get a defined short retention period and are then aggregated. Access to traces by support and ops is role-based and audited. Analytics use pseudonymous IDs."),
    s(3, "How would you approach a capacity estimate for the order and inventory services at peak?", "I'd begin with assumptions instead of invented facts: the number of stores, peak orders per store per minute, average lines per order, and browse-to-order ratios. Peak order writes equal stores times per-store peak rate. Reservation operations equal orders times lines, plus releases for abandoned carts, which can be a multiple of completed orders. Each store's throughput is physically capped by pickers and riders, so per-store load is bounded and scaling is mostly horizontal across stores. Redis handles single-key atomic operations very fast, so the real bottlenecks tend to be Postgres write volume for movements, payment callbacks and catalog reads. I'd validate the numbers with load tests at a multiple of the expected peak."),
    s(4, "How do you reserve a multi-line cart atomically so you never hold half an order?", "All keys for one order belong to the same store. I give them a hash tag like {store_id} so that in Redis Cluster they live in the same slot. A Lua script then checks availability for every line and, only if all lines pass, decrements each line and records the reservation hash with an expiry, all in one atomic execution. If any line fails, nothing changes, and the script returns the lines that failed so the UI can offer to drop them. Expiry is driven by a sorted set of reservation deadlines, which a sweeper releases idempotently. A per-key TTL alone can't restore counters by itself, so it isn't enough."),
    s(3, "A popular SKU in one store gets hit by thousands of checkouts in seconds. Does a single Redis key become a bottleneck?", "Per store, the physical order rate is limited by pickers and riders, so even a flash sale rarely exceeds what one Redis key handles. Single-key Lua operations are fast and run in a single thread, which is exactly what gives us correctness. The bigger risks are the shard holding many busy stores and retries amplifying load. I'd spread stores across shards and apply backoff with jitter on retries. At the edge, I'd rate-limit checkout attempts for the hot SKU. If needed, I'd queue checkouts for that store so they're served in order. I would avoid splitting one SKU's stock across multiple keys. It adds complexity and creates false 'out of stock' results when one bucket empties."),
    s(4, "What metrics and SLOs would you define to protect the 10-minute promise?", "I'd break the promise into stages and measure each one: serviceability and checkout latency, confirm-to-pick-start, pick duration, pack-to-handover, rider wait at the store, last-mile time, and finally on-time delivery rate against the promise. Correctness SLOs matter just as much: oversell incidents, which should be zero, short-pick rate, refund accuracy, and Redis-to-Postgres drift. I'd also track rider and bag idle times, substitution acceptance, and how often stores were throttled. Dashboards slice by store and hour. Alerts fire on burn rate rather than single spikes, and a missed promise links back to the stage that consumed the budget."),
    s(3, "A customer cancels after picking has started. How do you handle stock and money?", "Cancellation is a state transition the order service validates. Before handover, the system allows it. The pick task is stopped, and the picked items go back to their bins with a scan, which writes return movements so they become sellable again. Any remaining reservation is released. Payment follows the policy: a full refund, or an exact refund through the ledger, with authorisation voided where capture hasn't happened yet. After rider handover, the policy may block cancellation or treat it as a return. Every step is idempotent and event-driven, and dispatch is told to unassign the rider or re-batch. Perishables that can't be restocked are written off through an explicit adjustment movement."),
    s(3, "How do you detect and correct inventory drift between system stock and physical shelves?", "Drift comes from theft, damage, mis-shelving and scanning errors. Short picks are the strongest signal. I'd run cycle counts that prioritise high-velocity SKUs and SKUs with frequent shorts, and the counts are scanned on the store app. Each count writes an adjust movement with a reason code, so it appears in the ledger. Bins found empty while the system shows stock can be frozen immediately until counted, so they aren't shown as sellable. Analytics report drift per store and per category, and expiry checks write off stale perishables. A good forecast also depends on this, because drift that hides stockouts corrupts the censored-demand signal."),
    s(3, "How should inbound restock receiving work, and what if the delivered quantity doesn't match the purchase order?", "Inbound arrives against a transfer or purchase order from the warehouse. Store staff scan each case or unit, and then scan the bin where it's shelved. Only after the putaway scan does inventory write a receive movement and increase sellable stock. This avoids selling stock that's still in a crate at the back. Over-receipts and under-receipts are recorded against the order with reason codes and sent to the warehouse for reconciliation. Batch and expiry dates are captured for perishables, so picking can follow FEFO, first expiry first out. Damaged items are received into a non-sellable state. The planner sees the actual received quantities, not the ordered ones."),
    s(3, "How does the restock planner balance stockouts against waste for perishables?", "For each store and SKU, the planner takes the forecast distribution for the period until the next delivery. It sets an order-up-to level based on a service-level target, limited by shelf capacity and by how much can be sold before expiry. For perishables, the target service level is lower and the expiry cap is tighter, since unsold stock is pure loss. For long-life goods, a higher service level is worth it. The warehouse delivery schedule sets the review period. Then the planner subtracts on-hand and in-transit stock and rounds to case packs. I'd review waste and stockout rates per category to tune the targets."),
    s(3, "How would you handle a city-level outage of your primary region?", "Stores, inventory and orders are naturally partitioned by city, so I'd design the cell boundaries around cities or groups of cities to limit the blast radius. Postgres replicates to a standby in another zone or region. Redis inventory can be rebuilt from Postgres. Kafka has replicated topics. During failover, I would pause new orders for affected stores rather than risk overselling with stale stock. In-flight orders continue through the offline-capable store and rider apps. After the region recovers, I'd reconcile inventory, payment and ledger state before reopening. I'd rehearse this with game days, because a failover plan that's never been tested usually breaks in some unexpected way."),
    s(3, "Prices can change between browsing and checkout. How do you keep the charge consistent?", "The cart stores the price version shown to the user. At checkout, the order service re-prices from the current price book for that store and compares the two. If the price changed, the user sees the new total and confirms before payment. The confirmed order then snapshots unit price, discounts and taxes on each line, and all later billing, including partial refunds, uses those snapshots, never live prices. Coupons are validated and locked at the same point. This keeps refunds exact: a dropped line refunds its own snapshotted net amount, with discount allocation computed deterministically at order time."),
    s(2, "How would you prevent riders from spoofing GPS to game ETAs or incentives?", "Fake-location apps are common, so the server shouldn't trust the client blindly. The rider app checks for mock-location flags and integrity signals using platform attestation APIs. The server rejects impossible jumps and speeds and cross-checks the reported location against events with physical anchors: the bag scan at the store and the OTP at the customer. Unusual patterns, such as consistent teleporting or deliveries completed far from the address, feed a risk score. Riders with high scores get manual review. Incentives are calculated from verified events, not raw GPS distance, so spoofing gains them little."),
    s(2, "How would you test this workflow for correctness before a festival peak?", "I'd start with property-based tests on the reservation script: under concurrent reserve, commit, release and expiry, available stock never goes negative and the total stays conserved. I'd run contract tests between the order, inventory and payment services. Then I'd load-test with realistic carts at a multiple of the expected peak, including many abandoned carts that exercise expiry. For chaos, I'd kill a Redis primary, delay payment webhooks past the TTL, duplicate Kafka messages, and cut a store's network, then confirm there are no oversells, no duplicate charges, and that reconciliation is clean. A shadow ledger check verifies every refund equals the dropped line values."),
    s(2, "Would you use microservices for all of these steps, or merge some? Justify the boundaries.", "I'd separate by data ownership and scaling profile, not by step count. Serviceability and catalog are read-heavy and cache-friendly, so they can scale independently. Order and payment orchestration share transactional needs. Inventory must own stock and reservations with strict consistency. Store operations, meaning pick and pack, run close to the store and need offline support. Dispatch and tracking handle high-frequency geo data. Forecasting and planning are batch or streaming analytics in a separate stack. I'd avoid splitting order and payment orchestration too finely early on, because sagas across many services make compensation harder. The boundaries matter most where consistency or load differ sharply."),
  ],
  objective: [
    o(5, "Which mechanism best guarantees that a retried checkout request does not create a second order?", ["A unique constraint on a client-supplied idempotency key","Increasing the HTTP client timeout","Using Kafka with acks=all","Caching the order page in a CDN"], 0, "Storing the client's idempotency key under a unique constraint lets the server detect a retry and return the original order. A longer timeout or stronger broker acks do not stop a retry from creating a duplicate."),
    o(5, "How do you atomically check and decrement stock for several lines of one order in Redis?", ["Run separate DECR commands from the app and roll back on failure","Use a Lua script on keys sharing a hash tag so they live in one slot","Use the KEYS command to find stock keys first","Write to Redis replicas for higher throughput"], 1, "A Lua script runs atomically on one node, and a shared hash tag keeps all the keys in the same cluster slot. Separate DECR calls leave a window where only part of the order is reserved."),
    o(4, "What problem does the transactional outbox pattern solve for publishing order.confirmed?", ["It removes the need for consumers to deduplicate","It guarantees exactly-once processing in all consumers","It avoids the dual write where the DB commit and the Kafka publish can diverge","It compresses events to reduce Kafka storage"], 2, "The event is written in the same DB transaction as the state change and relayed afterwards, so the two cannot diverge. Delivery is still at least once, so consumers must deduplicate."),
    o(4, "Kafka guarantees message ordering at which level?", ["Across the whole cluster","Across all partitions of a topic","Per consumer group","Within a single partition"], 3, "Ordering holds only within a partition. Events for one order must therefore share a partition key."),
    o(4, "Why is rider matching started before packing is complete?", ["To overlap the rider's travel to the store with picking and packing","To reduce GPS ping frequency","To avoid generating pick lists","Because riders cannot be batched otherwise"], 0, "Overlapping the two activities removes the rider-search delay from the critical path, which matters inside a 10-minute budget."),
    o(4, "A batch of two orders on one rider should be accepted only when…", ["Both customers live in the same H3 cell at any resolution","Each order still meets its own promise along the combined route","The rider has the highest rating","The second order arrives within an hour"], 1, "Batching is opportunistic. It is acceptable only if neither order's delivery promise is broken."),
    o(5, "When a picker finds an empty bin and the customer rejects the substitute, what should happen?", ["Charge for the item and offer a coupon later","Hold the whole order until restock","Drop the line, correct inventory and refund the exact line amount via the ledger","Cancel the entire order automatically"], 2, "The workflow drops the short line, writes an inventory correction and issues an exact refund. The rest of the order continues."),
    o(3, "Which payment approach most directly avoids charging for items that are later dropped?", ["Capture the full cart amount immediately","Charge on delivery for all items regardless of shorts","Use a stored-value wallet only","Authorise at checkout and capture the final packed amount where the method supports it"], 3, "Capturing only the final amount means dropped items never get charged. For methods without separate authorisation, an exact refund serves as the fallback."),
    o(4, "In a double-entry ledger, how is a refund recorded?", ["As new reversing entries referencing the original","By editing the original payment entry amount","By deleting the order row","By updating a balance column only"], 0, "Ledger entries are immutable. A refund is posted as new entries, which keeps the audit trail intact."),
    o(4, "If Redis loses recent reservation writes after a failover, what is the safest response?", ["Keep selling and fix counts at night","Pause sales for affected stores and rebuild counters from Postgres","Set all stock counts to zero permanently","Trust the client cart quantities"], 1, "Postgres is the system of record. Rebuilding from it while sales are paused prevents overselling against stale counters."),
    o(3, "Why use a sorted set of expiry times instead of relying only on per-key TTL to release reservations?", ["Sorted sets use less memory than strings","TTLs are not supported in Redis Cluster","A key expiring does not restore the stock counter on its own","Sorted sets make reservations permanent"], 2, "When a reservation key expires, the decremented availability counter is not added back. A sweeper driven by deadlines releases the stock explicitly and idempotently."),
    o(4, "What should a Kafka consumer in the pick service do when it receives the same order.confirmed event twice?", ["Create a second pick list","Crash to force a manual check","Forward the duplicate to dispatch","Treat it as a no-op using the event or order ID"], 3, "Delivery is at least once, so consumers must be idempotent."),
    o(3, "Why does the catalog show only SKUs the specific store can sell right now?", ["To reduce failed reservations and avoid promising stock the store lacks","Because H3 requires it","To avoid storing prices","To skip checkout re-validation"], 0, "Showing only sellable SKUs cuts checkout failures. The reservation still acts as the final gate."),
    o(3, "Why does checkout re-check serviceability even though it was checked at app open?", ["To refresh the user's login token","Store load, open status or the user's location may have changed since browsing","To recompute the forecast","Because H3 cells expire"], 1, "Serviceability is time-sensitive. An overloaded or closed store must not receive new orders."),
    o(3, "Which technique best reduces jitter in live rider location shown to customers?", ["Sending pings less often","Showing only the destination","Filtering inaccurate points and smoothing, e.g., with a Kalman filter","Rounding coordinates to one decimal place"], 2, "Filtering and smoothing remove GPS noise but keep real movement. Coarse rounding destroys accuracy."),
    o(3, "Which protocol is used in this workflow to push live tracking updates to the customer app?", ["SMTP","FTP","Batch email digests","WebSocket"], 3, "A persistent WebSocket connection lets the server push ETA and location updates with low latency."),
    o(4, "What does the rider's bag scan at handover primarily establish?", ["A verified start of the last-mile leg and chain of custody","The customer's payment authorisation","The store's restock quantity","The picker's shift end"], 0, "The scan ties the specific bag to the rider and starts the last-mile tracking."),
    o(4, "Delivery OTP verification mainly protects against…", ["Picker errors in the store","Riders marking orders delivered without handing them over","Overselling during peak","Duplicate orders on retry"], 1, "The OTP comes from the customer, which proves the handover happened."),
    o(3, "When a store becomes overloaded, which response best protects the promise?", ["Accept all orders and add apology messages","Disable payments globally","Lengthen the promise, shrink coverage, then mark the store not serviceable","Route orders to stores in another city"], 2, "Gradual throttling keeps accepted orders within a promise the store can actually meet."),
    o(3, "Why add hysteresis to a store's open or closed load state?", ["To speed up checkout","To encrypt the state","To make H3 lookups faster","To stop the store flapping between serviceable and not serviceable"], 3, "Separate thresholds for closing and reopening prevent rapid toggling near the limit."),
    o(3, "When does inbound stock become sellable in this workflow?", ["After it is scanned on receipt and inventory is updated","When the truck leaves the warehouse","When the purchase order is created","When the forecast predicts demand"], 0, "Only scanned, recorded stock is sellable, which prevents selling items that are not on the shelf."),
    o(3, "For perishables, what is the main extra constraint the restock planner applies compared with long-life goods?", ["Larger case packs","A cap based on how much can sell before expiry","Ignoring the delivery schedule","Always targeting a 100% service level"], 1, "Unsold perishables become waste, so shelf life limits the order quantity."),
    o(3, "Which picking rule fits perishables best?", ["LIFO","Random bin choice","FEFO (first expiry, first out)","Highest price first"], 2, "Picking the earliest expiry first reduces waste and prevents customers from receiving short-dated stock."),
    o(4, "Why sort the pick list by bin location?", ["To randomise picker workload","To match the customer's cart order","To simplify payment","To minimise the picker's walking path"], 3, "A path-ordered list shortens pick time, which is a large part of the 10-minute budget."),
    o(4, "Which append-only table best supports auditing and reconciling stock?", ["inventory_movements with typed deltas and references","A single stock row overwritten on each change","Redis keys only","Order status history"], 0, "Typed movements such as reserve, commit, release, short and receive give a full, replayable history."),
    o(3, "Under India's DPDP Act, which practice best fits handling of customer delivery data?", ["Share addresses with all riders in the city","Collect only what delivery needs, mask phone numbers and limit retention","Store raw GPS traces forever for analytics","Email order details unencrypted"], 1, "Data minimisation, masking and limited retention match the purpose-limitation principles of the Act."),
    o(3, "A payment success webhook arrives after the reservation expired and the stock is gone. What is correct?", ["Ship the item anyway","Ignore the payment","Re-reserve; fulfil the available lines and refund the rest exactly","Ask the picker to find similar stock without telling the customer"], 2, "The system must never fulfil stock it lacks and must never keep money for undelivered items."),
    o(2, "Which partition key keeps each store's pick queue ordered and owned by one consumer?", ["user_id","sku_id","Random UUID per message","store_id"], 3, "Keying by store_id routes all of a store's orders to one partition in order. The trade-off is a possible hot spot."),
    o(2, "What is the main risk of splitting one SKU's stock across several Redis keys to spread load?", ["False out-of-stock results when one bucket empties while others hold stock","Redis cannot store integers","Lua scripts stop working","TTL becomes mandatory"], 0, "Split counters fragment the stock and make reservations more complex, which can produce false out-of-stock results."),
    o(2, "In this workflow, which signal is the strongest indicator of inventory drift at a store?", ["Number of app opens","Rate of short picks from empty bins","Average order value","Rider ratings"], 1, "A short pick means the system believed stock existed that was not physically there."),
  ],
};
export default bank;
